def _layout(name, price, currency, width, align, border, padding):
    text = f"{name} {currency}{price:.2f}"
    room = width - 2 * padding
    text = text.center(room) if align == "center" else text.ljust(room)
    inner = " " * padding + text + " " * padding
    if border:
        return "|" + inner + "|"
    return inner


def render_label(product, width=30, align="left", border=True):
    currency = product.get("currency", "$")
    return _layout(product["name"], product["price"], currency, width, align, border, 1)

