from labels.render import render_label


def test_left_aligned_with_border():
    assert render_label({"name": "Pen", "price": 1.5}) == "|" + " Pen $1.50".ljust(30) + "|"


def test_centered_without_border():
    label = render_label({"name": "Pen", "price": 1.5, "currency": "EUR"}, 20, "center", False)
    assert label == " " + "Pen EUR1.50".center(18) + " "
